1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface Damage {
9	  itemType: string;
10	  amount: number;
11	}
12	
13	export interface Incident {
14	  cause: string;
15	  damages: Damage[];
16	}
17	
18	export type Step =
19	  | { op: "quote"; items: Item[] }
20	  | { op: "claim"; policy: number; incident: Incident };
21	
22	export interface Scenario {
23	  customer: { yearsWithMHPCO: number };
24	  steps: Step[];
25	}
26	
27	export type QuoteResult = { premium: number };
28	export type ClaimResult = { payout: number; remainingCap: number };
29	export type Result = QuoteResult | ClaimResult;
30	
31	export interface ScenarioOutcome {
32	  results: Result[];
33	}
34	
35	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
36	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
37	
38	const BASE_PREMIUM: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	};
43	
44	const FIRST_INSURANCE_SURCHARGE = 1.1;
45	const POLICY_FEE = 5;
46	
47	const quote = (items: Item[]): QuoteResult => {
48	  const basePremium = BASE_PREMIUM[items[0].type];
49	  return { premium: roundUpToWholeG(basePremium * FIRST_INSURANCE_SURCHARGE) + POLICY_FEE };
50	};
51	
52	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
53	  const results = scenario.steps.map((step) => {
54	    if (step.op === "quote") return quote(step.items);
55	    throw new Error("claim steps are not implemented yet");
56	  });
57	  return { results };
58	};
